def est_valide(mdp):
    if len(mdp) < 8:
        return False
    maj = False
    chiffre = False
    for c in mdp:
        if c == ' ':
            return False
        if 'A' <= c <= 'Z':
            maj = True
        if '0' <= c <= '9':
            chiffre = True
    return maj and chiffre

assert est_valide('Nsi2026ok')
assert not est_valide('nsi2026ok')
assert not est_valide('Nsi 2026ok')
