def texte_unique(lignes):
    texte = ''
    for ligne in lignes:
        for c in ligne:
            if c == '\n':
                texte = texte + ' '
            else:
                texte = texte + c
    return texte

assert texte_unique(['Le chat\n', 'dort.\n']) == 'Le chat dort. '
